'use client';

import { Popover as PopoverPrimitive } from '@base-ui/react/popover';
import { addDays, addMonths } from 'date-fns';
import { AnimatePresence, motion } from 'motion/react';
import { useId, useState, type RefObject } from 'react';
import type { DateRange, Matcher } from 'react-day-picker';

import { WordRoll } from '@/components/core/word-roll';
import {
  typingSteps,
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useIsNarrow } from '@/registry/ndeko/hooks/use-is-narrow';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  hold,
  PRESS_LEAD_MS,
  pressedQuietOf,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import {
  CalendarIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
} from '@/registry/ndeko/lib/icons';
import { MENU_ITEM, POPUP_TRANSITION } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { Input } from '@/registry/ndeko/ui/input';
import { Label } from '@/registry/ndeko/ui/label';
import { SelectedMark } from '@/registry/ndeko/ui/selected-mark';
import { Switch } from '@/registry/ndeko/ui/switch';

import { AnimatedCalendar } from './_parts/animated-calendar';
import {
  PERIOD_PRESETS,
  periodTextOf,
  previousPeriodOf,
  readPeriod,
  type Period,
} from './_parts/period-words';
import { useToday } from './_parts/today';

type Step = 'periods' | 'days';

type Selection =
  { kind: 'phrase'; phrase: string } | { kind: 'days'; from: Date; to: Date };

type PressKey = 'typed' | 'days' | 'apply';

const REST_SELECTION: Selection = { kind: 'phrase', phrase: 'last 30 days' };

const SWAP_SHIFT_PX = 10;

const NARROW_REM = 36;

const MARK = 'transition-[scale,opacity] duration-150 ease-(--ease-out-strong)';

function markStateOf(isSelected: boolean) {
  if (isSelected) {
    return 'scale-100 opacity-100';
  }
  return 'scale-75 opacity-0 duration-100';
}

function periodOfSelection(selection: Selection | null, today: Date | null) {
  if (selection === null || today === null) {
    return null;
  }
  if (selection.kind === 'days') {
    return { from: selection.from, to: selection.to };
  }
  return readPeriod(selection.phrase, today);
}

function rangeOfSelection(
  selection: Selection | null,
  today: Date | null
): DateRange | undefined {
  const period = periodOfSelection(selection, today);
  if (period === null) {
    return undefined;
  }
  return { from: period.from, to: period.to };
}

function isPhraseSelected(selection: Selection | null, phrase: string) {
  if (selection === null || selection.kind !== 'phrase') {
    return false;
  }
  return selection.phrase === phrase;
}

function textOfPeriod(period: Period | null, today: Date | null) {
  if (period === null || today === null) {
    return 'Pick a period';
  }
  return periodTextOf(period, today);
}

function capitalized(text: string) {
  const trimmed = text.trim();
  return `${trimmed.charAt(0).toUpperCase()}${trimmed.slice(1)}`;
}

function isPreset(text: string) {
  const phrase = text.trim().toLowerCase();
  return PERIOD_PRESETS.some((preset) => preset.phrase === phrase);
}

function usePeriodPicker(today: Date | null) {
  const [isOpen, setIsOpen] = useState(true);
  const [step, setStep] = useState<Step>('periods');
  const [stepShift, setStepShift] = useState(1);
  const [text, setText] = useState('');
  const [draft, setDraft] = useState<Selection | null>(REST_SELECTION);
  const [compare, setCompare] = useState(false);
  const [dayRange, setDayRange] = useState<DateRange | undefined>();
  const [applied, setApplied] = useState<Selection | null>(REST_SELECTION);
  const [appliedCompare, setAppliedCompare] = useState(false);
  const typedPeriod = readTypedPeriod(text, today);

  function openPanel() {
    setDraft(applied);
    setCompare(appliedCompare);
    setStep('periods');
    setText('');
    setDayRange(rangeOfSelection(applied, today));
    setIsOpen(true);
  }

  function changeOpen(next: boolean) {
    if (next) {
      openPanel();
      return;
    }
    setIsOpen(false);
  }

  function selectPhrase(phrase: string) {
    setDraft({ kind: 'phrase', phrase });
  }

  function selectTyped() {
    if (typedPeriod === null) {
      return;
    }
    setDraft({ kind: 'phrase', phrase: text.trim().toLowerCase() });
  }

  function chooseDays(range: DateRange | undefined) {
    setDayRange(range);
    if (range?.from && range?.to) {
      setDraft({ kind: 'days', from: range.from, to: range.to });
    }
  }

  function showDays() {
    setStepShift(1);
    setStep('days');
  }

  function showPeriods() {
    setStepShift(-1);
    setStep('periods');
  }

  function apply() {
    setApplied(draft);
    setAppliedCompare(compare);
    setIsOpen(false);
  }

  function cancel() {
    setIsOpen(false);
  }

  function reset() {
    setIsOpen(true);
    setStep('periods');
    setText('');
    setDraft(REST_SELECTION);
    setCompare(false);
    setDayRange(undefined);
    setApplied(REST_SELECTION);
    setAppliedCompare(false);
  }

  return {
    isOpen,
    step,
    stepShift,
    text,
    changeText: setText,
    typedPeriod,
    draft,
    compare,
    changeCompare: setCompare,
    dayRange,
    applied,
    appliedCompare,
    changeOpen,
    selectPhrase,
    selectTyped,
    chooseDays,
    showDays,
    showPeriods,
    apply,
    cancel,
    reset,
  };
}

function readTypedPeriod(text: string, today: Date | null) {
  if (today === null) {
    return null;
  }
  return readPeriod(text, today);
}

type PeriodPickerState = ReturnType<typeof usePeriodPicker>;

type PeriodRowProps = {
  label: string;
  dates: string;
  isSelected: boolean;
  isPressed?: boolean;
  onSelect: () => void;
};

function PeriodRow({
  label,
  dates,
  isSelected,
  isPressed = false,
  onSelect,
}: PeriodRowProps) {
  return (
    <li>
      <button
        type='button'
        aria-pressed={isSelected}
        onClick={onSelect}
        className={cn(
          MENU_ITEM,
          'hover:bg-foreground/5 cursor-pointer justify-between gap-3 pr-1.5',
          pressedQuietOf(isPressed)
        )}
      >
        <span className='truncate'>{label}</span>
        <span className='text-muted-foreground flex shrink-0 items-center gap-2 text-xs tabular-nums'>
          {dates}
          <SelectedMark className={cn(MARK, markStateOf(isSelected))} />
        </span>
      </button>
    </li>
  );
}

type PanelProps = {
  picker: PeriodPickerState;
  today: Date | null;
  isTwoUp: boolean;
  pressed: PressKey | null;
};

function triggerLabelOf(today: Date | null, text: string) {
  if (today === null) {
    return <span>{text}</span>;
  }
  return <WordRoll text={text} />;
}

function readsAsOf(
  text: string,
  typedPeriod: Period | null,
  today: Date | null
) {
  if (text.trim() === '') {
    return 'Try “last 2 weeks”, “Q3” or “since sep 3”';
  }
  if (typedPeriod === null || today === null) {
    return 'Can’t read that yet';
  }
  return `Reads as ${periodTextOf(typedPeriod, today)}`;
}

function PeriodsStep({ picker, today, pressed }: PanelProps) {
  const { text, changeText, typedPeriod, draft, selectPhrase, selectTyped } =
    picker;
  const readsAs = readsAsOf(text, typedPeriod, today);
  const showsTypedRow = typedPeriod !== null && !isPreset(text);
  const typedPhrase = text.trim().toLowerCase();

  function selectOnEnter(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Enter') {
      return;
    }
    event.preventDefault();
    selectTyped();
  }

  return (
    <div className='flex w-[min(20rem,calc(100vw-4rem))] flex-col gap-2'>
      <Input
        aria-label='Period'
        value={text}
        onChange={(event) => changeText(event.currentTarget.value)}
        onKeyDown={selectOnEnter}
        placeholder='Type a period'
        autoComplete='off'
        spellCheck={false}
      />
      <div className='text-muted-foreground flex min-h-4 items-center px-0.5 text-xs'>
        <WordRoll text={readsAs} />
      </div>
      <ul className='flex flex-col'>
        {showsTypedRow && typedPeriod && (
          <PeriodRow
            label={capitalized(text)}
            dates={textOfPeriod(typedPeriod, today)}
            isSelected={isPhraseSelected(draft, typedPhrase)}
            isPressed={pressed === 'typed'}
            onSelect={selectTyped}
          />
        )}
        {PERIOD_PRESETS.map((preset) => (
          <PeriodRow
            key={preset.phrase}
            label={preset.label}
            dates={textOfPeriod(readTypedPeriod(preset.phrase, today), today)}
            isSelected={isPhraseSelected(draft, preset.phrase)}
            onSelect={() => selectPhrase(preset.phrase)}
          />
        ))}
      </ul>
    </div>
  );
}

function DaysStep({ picker, today, isTwoUp }: PanelProps) {
  const { dayRange, chooseDays, showPeriods, draft } = picker;
  const monthCount = twoUpCountOf(isTwoUp);
  const firstShownMonth = firstShownMonthOf(today, monthCount);
  const futureMatcher = futureMatcherOf(today);
  const draftText = textOfPeriod(periodOfSelection(draft, today), today);
  const calendarKey = `${monthCount}`;

  return (
    <div className='flex flex-col gap-1'>
      <div className='flex items-center justify-between gap-3'>
        <Button
          variant='ghost'
          size='sm'
          onClick={showPeriods}
          className='-ms-2'
        >
          <ChevronLeftIcon className='size-3.5' />
          Periods
        </Button>
        <span className='text-muted-foreground text-xs tabular-nums'>
          <WordRoll text={draftText} />
        </span>
      </div>
      <AnimatedCalendar
        key={calendarKey}
        mode='range'
        numberOfMonths={monthCount}
        selected={dayRange}
        onSelect={chooseDays}
        defaultMonth={firstShownMonth}
        disabled={futureMatcher}
      />
    </div>
  );
}

function firstShownMonthOf(today: Date | null, monthCount: number) {
  if (today === null) {
    return undefined;
  }
  return addMonths(today, -(monthCount - 1));
}

function futureMatcherOf(today: Date | null): Matcher | undefined {
  if (today === null) {
    return undefined;
  }
  return { after: today };
}

function twoUpCountOf(isTwoUp: boolean) {
  if (isTwoUp) {
    return 2;
  }
  return 1;
}

function stepVariantsOf(shouldReduceMotion: boolean | null) {
  const shift = SWAP_SHIFT_PX;
  if (shouldReduceMotion) {
    return {
      enter: { opacity: 0 },
      center: { opacity: 1 },
      leave: { opacity: 0 },
    };
  }
  return {
    enter: (direction: number) => ({ opacity: 0, x: direction * shift }),
    center: { opacity: 1, x: 0 },
    leave: (direction: number) => ({ opacity: 0, x: -direction * shift }),
  };
}

function PanelFooter({
  picker,
  today,
  pressed,
}: Pick<PanelProps, 'picker' | 'today' | 'pressed'>) {
  const compareId = useId();
  const { compare, changeCompare, draft, apply, cancel } = picker;
  const period = periodOfSelection(draft, today);
  const hasPeriod = period !== null;
  const showsPrevious = compare && hasPeriod && today !== null;
  let previousText = '';
  if (period !== null && today !== null) {
    previousText = periodTextOf(previousPeriodOf(period), today);
  }

  return (
    <div className='flex flex-col gap-2'>
      <div className='flex items-center justify-between gap-3'>
        <Label htmlFor={compareId} className='font-normal'>
          Compare with previous period
        </Label>
        <Switch
          id={compareId}
          checked={compare}
          onCheckedChange={changeCompare}
        />
      </div>
      <Fold open={showsPrevious}>
        <p className='text-muted-foreground flex gap-1 text-xs'>
          Previous
          <WordRoll text={previousText} className='text-foreground' />
        </p>
      </Fold>
      <div className='flex justify-end gap-2'>
        <Button variant='ghost' size='sm' onClick={cancel}>
          Cancel
        </Button>
        <Button
          size='sm'
          disabled={!hasPeriod}
          onClick={apply}
          className={pressedQuietOf(pressed === 'apply')}
        >
          Apply
        </Button>
      </div>
    </div>
  );
}

type PeriodPickerProps = {
  picker: PeriodPickerState;
  today: Date | null;
  /** The element the panel is drawn in, so it stays inside the component. */
  container: RefObject<HTMLElement | null>;
  isTwoUp: boolean;
  /** True while a demonstration plays: it neither takes the focus nor gives it back. */
  isDemonstrating: boolean;
  pressed?: PressKey | null;
};

export function PeriodPicker({
  picker,
  today,
  container,
  isTwoUp,
  isDemonstrating,
  pressed = null,
}: PeriodPickerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = stepVariantsOf(shouldReduceMotion);
  const keepsFocus = !isDemonstrating;
  const appliedPeriod = periodOfSelection(picker.applied, today);
  const triggerText = textOfPeriod(appliedPeriod, today);
  let previousText = '';
  if (appliedPeriod !== null && today !== null) {
    previousText = periodTextOf(previousPeriodOf(appliedPeriod), today);
  }
  const showsComparison = picker.appliedCompare && appliedPeriod !== null;
  const panelProps = { picker, today, isTwoUp, pressed };

  return (
    <PopoverPrimitive.Root
      open={picker.isOpen}
      onOpenChange={picker.changeOpen}
    >
      <div className='flex w-full max-w-xs flex-col gap-1.5'>
        <PopoverPrimitive.Trigger
          render={
            <Button
              variant='outline'
              className='w-full justify-between font-normal'
              aria-label={`Period: ${triggerText}`}
            />
          }
        >
          {triggerLabelOf(today, triggerText)}
          <CalendarIcon className='text-muted-foreground size-4' />
        </PopoverPrimitive.Trigger>
        <Fold open={showsComparison}>
          <p className='text-muted-foreground flex gap-1 px-1 text-xs'>
            Compared with
            <WordRoll text={previousText} className='text-foreground' />
          </p>
        </Fold>
      </div>
      <PopoverPrimitive.Portal container={container}>
        <PopoverPrimitive.Positioner
          side='bottom'
          align='start'
          sideOffset={6}
          className='z-50'
        >
          <PopoverPrimitive.Popup
            initialFocus={false}
            finalFocus={keepsFocus}
            className={cn(
              'surface-raised max-w-(--available-width) rounded-xl p-3 text-[13px] outline-none',
              POPUP_TRANSITION
            )}
          >
            <AnimatedSize axis='both'>
              <div className='flex flex-col gap-3'>
                <div className='relative'>
                  <AnimatePresence
                    mode='popLayout'
                    initial={false}
                    custom={picker.stepShift}
                  >
                    <motion.div
                      key={picker.step}
                      custom={picker.stepShift}
                      variants={variants}
                      initial='enter'
                      animate='center'
                      exit='leave'
                      transition={{ duration: 0.18, ease: [0.23, 1, 0.32, 1] }}
                    >
                      {picker.step === 'periods' && (
                        <PeriodsStep {...panelProps} />
                      )}
                      {picker.step === 'days' && <DaysStep {...panelProps} />}
                    </motion.div>
                  </AnimatePresence>
                </div>
                {picker.step === 'periods' && (
                  <Button
                    variant='ghost'
                    size='sm'
                    onClick={picker.showDays}
                    className={cn(
                      'justify-between',
                      pressedQuietOf(pressed === 'days')
                    )}
                  >
                    Pick exact days
                    <ChevronRightIcon className='size-3.5 opacity-60' />
                  </Button>
                )}
                <PanelFooter picker={picker} today={today} pressed={pressed} />
              </div>
            </AnimatedSize>
          </PopoverPrimitive.Popup>
        </PopoverPrimitive.Positioner>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

export default function CalendarDatePicker30() {
  const today = useToday();
  const picker = usePeriodPicker(today);
  const { pressed, press } = usePress<PressKey>();

  function chooseDemoDays(isComplete: boolean) {
    if (today === null) {
      return;
    }
    const from = addDays(today, -12);
    if (!isComplete) {
      picker.chooseDays({ from, to: undefined });
      return;
    }
    picker.chooseDays({ from, to: addDays(today, -4) });
  }

  const steps: AutoplayStep[] = [
    { after: 2400, run: hold },
    ...typingSteps('since sep 3', picker.changeText, {
      startAfter: 400,
      characterMs: 70,
    }),
    { after: 900, run: () => press('typed') },
    { after: PRESS_LEAD_MS, run: picker.selectTyped },
    { after: 1500, run: () => picker.changeCompare(true) },
    { after: 1800, run: () => press('days') },
    { after: PRESS_LEAD_MS, run: picker.showDays },
    { after: 1400, run: () => chooseDemoDays(false) },
    { after: 700, run: () => chooseDemoDays(true) },
    { after: 1600, run: () => press('apply') },
    { after: PRESS_LEAD_MS, run: picker.apply },
    { after: 3000, run: hold },
  ];
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: 1800,
    onReset: picker.reset,
  });
  const isNarrow = useIsNarrow(ref, NARROW_REM);

  useKeptHeight(ref);

  return (
    <div ref={ref} className='relative min-h-[34rem] w-full max-w-2xl'>
      <PeriodPicker
        picker={picker}
        today={today}
        container={ref}
        isTwoUp={!isNarrow}
        isDemonstrating={isAutoplaying}
        pressed={pressed}
      />
    </div>
  );
}

'use client';

import { differenceInCalendarDays } from 'date-fns';
import {
  motion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';
import { useState } from 'react';
import {
  Day,
  useDayPicker,
  type DayProps,
  type MonthProps,
} from 'react-day-picker';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Calendar } from '@/registry/ndeko/ui/calendar';

type CalendarProps = React.ComponentProps<typeof Calendar>;

type ShownMonth = { time: number; direction: number };

const MONTH_SHIFT_PX = 12;
const RANGE_STEP_MS = 12;
const RANGE_GROWTH_MAX_MS = 240;

const MONTH_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const MONTH_AT_REST: TargetAndTransition = { opacity: 1, x: 0 };

const SETTLING_DAY_BUTTON = [
  'transition-[color,background-color,border-radius,box-shadow,scale] ease-(--ease-out-strong) active:scale-90',
  'group-[.range-middle]:[transition-delay:var(--range-delay),var(--range-delay),0ms,0ms,0ms]',
].join(' ');

function rangeStartOf(selected: unknown) {
  if (!selected) {
    return undefined;
  }
  if (typeof selected !== 'object') {
    return undefined;
  }
  if (!('from' in selected)) {
    return undefined;
  }
  return selected.from as Date | undefined;
}

function rangeDelayOf(day: Date, rangeStart: Date | undefined) {
  if (!rangeStart) {
    return '0ms';
  }
  const step = differenceInCalendarDays(day, rangeStart);
  const delay = Math.min(step * RANGE_STEP_MS, RANGE_GROWTH_MAX_MS);
  const positiveDelay = Math.max(0, delay);
  return `${positiveDelay}ms`;
}

function monthEnterOf(direction: number, shouldReduceMotion: boolean | null) {
  if (direction === 0) {
    return false;
  }
  if (shouldReduceMotion) {
    return { opacity: 0 };
  }
  const offset = direction * MONTH_SHIFT_PX;
  return { opacity: 0, x: offset };
}

function GrowingRangeDay({ style, ...props }: DayProps) {
  const { selected } = useDayPicker();
  const rangeStart = rangeStartOf(selected);
  const delay = rangeDelayOf(props.day.date, rangeStart);
  const dayStyle = { ...style, '--range-delay': delay } as React.CSSProperties;

  return <Day {...props} style={dayStyle} />;
}

function SlidingMonth({
  calendarMonth,
  displayIndex,
  children,
  ...props
}: MonthProps) {
  const time = calendarMonth.date.getTime();
  const [shown, setShown] = useState<ShownMonth>({ time, direction: 0 });
  const shouldReduceMotion = usePrefersReducedMotion();

  if (shown.time !== time) {
    const direction = Math.sign(time - shown.time);
    setShown({ time, direction });
  }

  return (
    <div data-display-index={displayIndex} {...props}>
      <AnimatedSize>
        <motion.div
          key={time}
          initial={monthEnterOf(shown.direction, shouldReduceMotion)}
          animate={MONTH_AT_REST}
          transition={MONTH_TRANSITION}
        >
          {children}
        </motion.div>
      </AnimatedSize>
    </div>
  );
}

function withSettlingDays(classNames: CalendarProps['classNames']) {
  const dayButton = cn(SETTLING_DAY_BUTTON, classNames?.day_button);
  return { ...classNames, day_button: dayButton };
}

/**
 * The calendar primitive with the date picker micro-interactions: a picked day settles in,
 * a range grows from its start to its end, a new month slides in from the side it comes from
 * and the card resizes to the number of weeks.
 */
function AnimatedCalendar({ classNames, components, ...props }: CalendarProps) {
  return (
    <Calendar
      classNames={withSettlingDays(classNames)}
      components={{ Day: GrowingRangeDay, Month: SlidingMonth, ...components }}
      {...props}
    />
  );
}

export { AnimatedCalendar };

import {
  addDays,
  addMonths,
  addYears,
  differenceInCalendarDays,
  endOfMonth,
  endOfQuarter,
  endOfYear,
  format,
  isAfter,
  isBefore,
  isSameDay,
  isSameYear,
  startOfMonth,
  startOfQuarter,
  startOfWeek,
  startOfYear,
} from 'date-fns';

import { monthIndexOf, readTypedDate } from './typed-date';

export type Period = {
  from: Date;
  to: Date;
};

export type PeriodPreset = {
  phrase: string;
  label: string;
};

const COUNTED_PERIOD = /^(?:last|past) (\d+) (days?|weeks?|months?)$/;
const QUARTER_PERIOD = /^q([1-4])(?: (\d{4}))?$/;
const SINCE_PERIOD = /^since (.+)$/;

const MONDAY = 1;

export const PERIOD_PRESETS: PeriodPreset[] = [
  { phrase: 'last 7 days', label: 'Last 7 days' },
  { phrase: 'last 30 days', label: 'Last 30 days' },
  { phrase: 'this month', label: 'This month' },
  { phrase: 'last month', label: 'Last month' },
  { phrase: 'this quarter', label: 'This quarter' },
  { phrase: 'year to date', label: 'Year to date' },
];

function normalized(text: string) {
  return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

function lastDaysOf(today: Date, days: number): Period {
  return { from: addDays(today, -(days - 1)), to: today };
}

function countedPeriodOf(match: RegExpMatchArray, today: Date): Period | null {
  const amount = Number(match[1]);
  if (amount < 1) {
    return null;
  }
  const unit = match[2][0];
  if (unit === 'w') {
    return lastDaysOf(today, amount * 7);
  }
  if (unit === 'm') {
    const from = addDays(addMonths(today, -amount), 1);
    return { from, to: today };
  }
  return lastDaysOf(today, amount);
}

function earlierDateOf(first: Date, second: Date) {
  if (isBefore(first, second)) {
    return first;
  }
  return second;
}

function quarterPeriodOf(match: RegExpMatchArray, today: Date): Period | null {
  const quarter = Number(match[1]);
  const year = Number(match[2] ?? today.getFullYear());
  const from = new Date(year, (quarter - 1) * 3, 1);
  if (isAfter(from, today)) {
    return null;
  }
  const to = earlierDateOf(endOfQuarter(from), today);
  return { from, to };
}

function sincePeriodOf(match: RegExpMatchArray, today: Date): Period | null {
  const reading = readTypedDate(match[1], {
    today,
    withTime: false,
    direction: 'past',
  });
  if (reading.status !== 'ready') {
    return null;
  }
  const from = reading.value.date;
  if (isAfter(from, today)) {
    return null;
  }
  return { from, to: today };
}

/** A month named on its own is its latest one: "sep" in November is this September, "dec" is last December. */
function monthPeriodOf(text: string, today: Date): Period | null {
  const month = monthIndexOf(text);
  if (month === -1) {
    return null;
  }
  const isLater = month > today.getMonth();
  let year = today.getFullYear();
  if (isLater) {
    year -= 1;
  }
  const from = new Date(year, month, 1);
  return { from, to: earlierDateOf(endOfMonth(from), today) };
}

function namedPeriodOf(text: string, today: Date): Period | null {
  const weekStart = startOfWeek(today, { weekStartsOn: MONDAY });
  const lastMonth = addMonths(today, -1);
  const lastQuarterStart = addMonths(startOfQuarter(today), -3);
  const lastYear = addYears(today, -1);
  if (text === 'today') {
    return { from: today, to: today };
  }
  if (text === 'yesterday') {
    const yesterday = addDays(today, -1);
    return { from: yesterday, to: yesterday };
  }
  if (text === 'this week') {
    return { from: weekStart, to: today };
  }
  if (text === 'last week') {
    const from = addDays(weekStart, -7);
    return { from, to: addDays(from, 6) };
  }
  if (text === 'this month') {
    return { from: startOfMonth(today), to: today };
  }
  if (text === 'last month') {
    return { from: startOfMonth(lastMonth), to: endOfMonth(lastMonth) };
  }
  if (text === 'this quarter') {
    return { from: startOfQuarter(today), to: today };
  }
  if (text === 'last quarter') {
    return { from: lastQuarterStart, to: endOfQuarter(lastQuarterStart) };
  }
  if (text === 'this year' || text === 'year to date' || text === 'ytd') {
    return { from: startOfYear(today), to: today };
  }
  if (text === 'last year') {
    return { from: startOfYear(lastYear), to: endOfYear(lastYear) };
  }
  return null;
}

export function readPeriod(text: string, today: Date): Period | null {
  const clean = normalized(text);
  if (clean === '') {
    return null;
  }
  const named = namedPeriodOf(clean, today);
  if (named) {
    return named;
  }
  const counted = clean.match(COUNTED_PERIOD);
  if (counted) {
    return countedPeriodOf(counted, today);
  }
  const quarter = clean.match(QUARTER_PERIOD);
  if (quarter) {
    return quarterPeriodOf(quarter, today);
  }
  const since = clean.match(SINCE_PERIOD);
  if (since) {
    return sincePeriodOf(since, today);
  }
  return monthPeriodOf(clean, today);
}

export function previousPeriodOf(period: Period): Period {
  const length = differenceInCalendarDays(period.to, period.from) + 1;
  const to = addDays(period.from, -1);
  const from = addDays(to, -(length - 1));
  return { from, to };
}

function dayTextOf(date: Date, hasYear: boolean) {
  if (hasYear) {
    return format(date, 'MMM d, y');
  }
  return format(date, 'MMM d');
}

export function periodTextOf(period: Period, today: Date) {
  const isFromThisYear = isSameYear(period.from, today);
  const isToThisYear = isSameYear(period.to, today);
  const hasYear = !isFromThisYear || !isToThisYear;
  const from = dayTextOf(period.from, hasYear);
  if (isSameDay(period.from, period.to)) {
    return from;
  }
  const to = dayTextOf(period.to, hasYear);
  return `${from} to ${to}`;
}

'use client';

import { startOfDay } from 'date-fns';
import { useSyncExternalStore } from 'react';

let cachedToday: Date | null = null;

function subscribeNever() {
  return () => {};
}

function readToday() {
  if (cachedToday === null) {
    cachedToday = startOfDay(new Date());
  }
  return cachedToday;
}

function readNothing() {
  return null;
}

/** The server and the first client render know no day, so what depends on it appears once the page is live. */
export function useToday() {
  return useSyncExternalStore(subscribeNever, readToday, readNothing);
}

import {
  addDays,
  addMonths,
  addWeeks,
  addYears,
  format,
  isAfter,
  isBefore,
  isSameYear,
  startOfDay,
} from 'date-fns';

export type TypedDate = {
  date: Date;
  hasTime: boolean;
};

export type TypedDateOptions = {
  today: Date;
  withTime: boolean;
  /** Which of day and month comes first in numbers such as 14/11. */
  isDayFirst?: boolean;
  /** Where a date with no year lands: the next time it comes round, or the last time it did. */
  direction?: 'future' | 'past';
};

export type TypedDateReading =
  | { status: 'empty' }
  | { status: 'unreadable' }
  | { status: 'ready'; value: TypedDate };

type Clock = {
  hours: number;
  minutes: number;
};

type Parts = {
  year: number;
  month: number;
  day: number;
};

const MONTHS = [
  'january',
  'february',
  'march',
  'april',
  'may',
  'june',
  'july',
  'august',
  'september',
  'october',
  'november',
  'december',
];

const WEEKDAYS = [
  'sunday',
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
];

const WEEKDAY_LEADS = ['', 'this', 'next', 'on'];

const MERIDIEM_TIME = /\b(?:at\s+)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/;
const CLOCK_TIME = /\b(?:at\s+)?(\d{1,2}):(\d{2})\b/;
const NOON = /\b(?:at\s+)?noon\b/;
const ISO_DATE = /^(\d{4})-(\d{1,2})-(\d{1,2})$/;
const NUMERIC_DATE = /^(\d{1,2})[./-](\d{1,2})(?:[./-](\d{4}|\d{2}))?$/;
const RELATIVE_DATE = /^in (\d+) (days?|d|weeks?|w|months?|years?|y)$/;
const ORDINAL_SUFFIX = /^(\d{1,2})(?:st|nd|rd|th)$/;

function normalized(text: string) {
  const lower = text.toLowerCase().replace(/,/g, ' ');
  const spaced = lower.replace(/(\d)t(\d)/g, '$1 $2');
  return spaced.replace(/\s+/g, ' ').trim();
}

function withoutMatch(text: string, match: RegExpMatchArray) {
  const before = text.slice(0, match.index);
  const after = text.slice((match.index ?? 0) + match[0].length);
  return `${before} ${after}`.replace(/\s+/g, ' ').trim();
}

function meridiemClockOf(match: RegExpMatchArray): Clock | null {
  const hour = Number(match[1]);
  const minutes = Number(match[2] ?? '0');
  const isHourValid = hour >= 1 && hour <= 12;
  const isMinuteValid = minutes <= 59;
  if (!isHourValid || !isMinuteValid) {
    return null;
  }
  const isPm = match[3] === 'pm';
  const hoursOfDay = hour % 12;
  if (isPm) {
    return { hours: hoursOfDay + 12, minutes };
  }
  return { hours: hoursOfDay, minutes };
}

function clockOf(match: RegExpMatchArray): Clock | null {
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  const isValid = hours <= 23 && minutes <= 59;
  if (!isValid) {
    return null;
  }
  return { hours, minutes };
}

type TimeSplit = {
  rest: string;
  clock: Clock | null;
  isBroken: boolean;
};

function splitTime(text: string): TimeSplit {
  const meridiem = text.match(MERIDIEM_TIME);
  if (meridiem) {
    const clock = meridiemClockOf(meridiem);
    return {
      rest: withoutMatch(text, meridiem),
      clock,
      isBroken: clock === null,
    };
  }
  const clockMatch = text.match(CLOCK_TIME);
  if (clockMatch) {
    const clock = clockOf(clockMatch);
    return {
      rest: withoutMatch(text, clockMatch),
      clock,
      isBroken: clock === null,
    };
  }
  const noon = text.match(NOON);
  if (noon) {
    return {
      rest: withoutMatch(text, noon),
      clock: { hours: 12, minutes: 0 },
      isBroken: false,
    };
  }
  return { rest: text, clock: null, isBroken: false };
}

function isRealDate({ year, month, day }: Parts) {
  const date = new Date(year, month, day);
  const isSameYearNumber = date.getFullYear() === year;
  const isSameMonth = date.getMonth() === month;
  const isSameDay = date.getDate() === day;
  return isSameYearNumber && isSameMonth && isSameDay;
}

function dateOfParts(parts: Parts) {
  if (!isRealDate(parts)) {
    return null;
  }
  return new Date(parts.year, parts.month, parts.day);
}

/** With no year, "14 nov" typed in December means next year, unless the field looks back in time. */
function withNearestYear(
  parts: Parts,
  today: Date,
  direction: 'future' | 'past'
) {
  const thisYear = dateOfParts(parts);
  if (thisYear === null) {
    return null;
  }
  if (direction === 'past') {
    if (!isAfter(thisYear, today)) {
      return thisYear;
    }
    return dateOfParts({ ...parts, year: parts.year - 1 });
  }
  if (!isBefore(thisYear, today)) {
    return thisYear;
  }
  return dateOfParts({ ...parts, year: parts.year + 1 });
}

export function monthIndexOf(word: string) {
  if (word.length < 3) {
    return -1;
  }
  return MONTHS.findIndex((name) => name.startsWith(word));
}

function weekdayIndexOf(word: string) {
  if (word.length < 3) {
    return -1;
  }
  return WEEKDAYS.findIndex((name) => name.startsWith(word));
}

function dayNumberOf(word: string) {
  const ordinal = word.match(ORDINAL_SUFFIX);
  if (ordinal) {
    return Number(ordinal[1]);
  }
  if (/^\d{1,2}$/.test(word)) {
    return Number(word);
  }
  return null;
}

function weekdayDateOf(today: Date, weekday: number, isNext: boolean) {
  const gap = (weekday - today.getDay() + 7) % 7;
  const mustBeLater = isNext && gap === 0;
  if (mustBeLater) {
    return addDays(today, 7);
  }
  return addDays(today, gap);
}

function relativeDateOf(match: RegExpMatchArray, today: Date) {
  const amount = Number(match[1]);
  const unit = match[2][0];
  if (unit === 'w') {
    return addWeeks(today, amount);
  }
  if (unit === 'm') {
    return addMonths(today, amount);
  }
  if (unit === 'y') {
    return addYears(today, amount);
  }
  return addDays(today, amount);
}

function keywordDateOf(text: string, today: Date) {
  if (text === '' || text === 'today') {
    return today;
  }
  if (text === 'tomorrow' || text === 'tmrw') {
    return addDays(today, 1);
  }
  if (text === 'yesterday') {
    return addDays(today, -1);
  }
  if (text === 'next week') {
    return addWeeks(today, 1);
  }
  if (text === 'next month') {
    return addMonths(today, 1);
  }
  return null;
}

function weekdayPhraseDateOf(text: string, today: Date) {
  const words = text.split(' ');
  const word = words[words.length - 1];
  const lead = words.slice(0, -1).join(' ');
  const hasKnownLead = WEEKDAY_LEADS.includes(lead);
  const weekday = weekdayIndexOf(word);
  if (!hasKnownLead || weekday === -1) {
    return null;
  }
  return weekdayDateOf(today, weekday, lead === 'next');
}

type DayAndMonth = {
  day: number;
  month: number;
};

/** A month that cannot be one (14/11 read month first) is taken the other way round. */
function dayAndMonthOf(
  first: number,
  second: number,
  isDayFirst: boolean
): DayAndMonth {
  const ordered = { day: second, month: first };
  if (isDayFirst) {
    ordered.day = first;
    ordered.month = second;
  }
  const needsSwap = ordered.month > 12 && ordered.day <= 12;
  if (needsSwap) {
    return { day: ordered.month, month: ordered.day };
  }
  return ordered;
}

function numericDateOf(match: RegExpMatchArray, options: TypedDateOptions) {
  const first = Number(match[1]);
  const second = Number(match[2]);
  const rawYear = match[3];
  const isDayFirst = options.isDayFirst ?? false;
  const { day, month } = dayAndMonthOf(first, second, isDayFirst);
  return datePartsDateOf(day, month - 1, rawYear, options);
}

function datePartsDateOf(
  day: number,
  month: number,
  rawYear: string | undefined,
  options: TypedDateOptions
) {
  const { today, direction = 'future' } = options;
  if (rawYear === undefined) {
    const parts = { year: today.getFullYear(), month, day };
    return withNearestYear(parts, today, direction);
  }
  const year = fullYearOf(rawYear);
  return dateOfParts({ year, month, day });
}

function fullYearOf(rawYear: string) {
  const year = Number(rawYear);
  if (rawYear.length === 2) {
    return 2000 + year;
  }
  return year;
}

function monthNameDateOf(text: string, options: TypedDateOptions) {
  const words = text.split(' ').filter((word) => word !== 'of');
  const isShort = words.length === 2 || words.length === 3;
  if (!isShort) {
    return null;
  }
  const [first, second, third] = words;
  const dayFirst = dayNumberOf(first);
  const monthSecond = monthIndexOf(second);
  if (dayFirst !== null && monthSecond !== -1) {
    return datePartsDateOf(dayFirst, monthSecond, third, options);
  }
  const monthFirst = monthIndexOf(first);
  const daySecond = dayNumberOf(second);
  if (monthFirst !== -1 && daySecond !== null) {
    return datePartsDateOf(daySecond, monthFirst, third, options);
  }
  return null;
}

function dateOfText(text: string, options: TypedDateOptions) {
  const { today } = options;
  const keyword = keywordDateOf(text, today);
  if (keyword) {
    return keyword;
  }
  const weekday = weekdayPhraseDateOf(text, today);
  if (weekday) {
    return weekday;
  }
  const relative = text.match(RELATIVE_DATE);
  if (relative) {
    return relativeDateOf(relative, today);
  }
  const iso = text.match(ISO_DATE);
  if (iso) {
    return dateOfParts({
      year: Number(iso[1]),
      month: Number(iso[2]) - 1,
      day: Number(iso[3]),
    });
  }
  const numeric = text.match(NUMERIC_DATE);
  if (numeric) {
    return numericDateOf(numeric, options);
  }
  return monthNameDateOf(text, options);
}

export function readTypedDate(
  text: string,
  options: TypedDateOptions
): TypedDateReading {
  const clean = normalized(text);
  if (clean === '') {
    return { status: 'empty' };
  }
  const { rest, clock, isBroken } = splitTime(clean);
  if (isBroken) {
    return { status: 'unreadable' };
  }
  const isTimeAllowed = options.withTime || clock === null;
  if (!isTimeAllowed) {
    return { status: 'unreadable' };
  }
  const day = dateOfText(rest, options);
  if (day === null) {
    return { status: 'unreadable' };
  }
  const start = startOfDay(day);
  if (clock === null) {
    return { status: 'ready', value: { date: start, hasTime: false } };
  }
  const withClock = new Date(start);
  withClock.setHours(clock.hours, clock.minutes, 0, 0);
  return { status: 'ready', value: { date: withClock, hasTime: true } };
}

function dayPatternOf(hasThisYear: boolean) {
  if (hasThisYear) {
    return 'EEEE d MMMM';
  }
  return 'EEEE d MMMM y';
}

export function describeTypedDate(value: TypedDate, today: Date) {
  const hasThisYear = isSameYear(value.date, today);
  const dayPattern = dayPatternOf(hasThisYear);
  const day = format(value.date, dayPattern);
  if (!value.hasTime) {
    return day;
  }
  const time = format(value.date, 'HH:mm');
  return `${day}, ${time}`;
}

export function formatTypedDate(value: TypedDate) {
  const day = format(value.date, 'd MMM y');
  if (!value.hasTime) {
    return day;
  }
  const time = format(value.date, 'HH:mm');
  return `${day}, ${time}`;
}

export function isDayFirstIn(locale: string) {
  const sample = new Date(2026, 10, 13);
  const parts = new Intl.DateTimeFormat(locale).formatToParts(sample);
  const order = parts.map((part) => part.type);
  return order.indexOf('day') < order.indexOf('month');
}
